PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://w3id.org/brick/2.2/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?point ?ts WHERE {
  ?point a brick:Electric_Power ;
         brick:isPartOf ?b .
  FILTER (STRSTARTS(STR(?b), "http://w3id.org/")) .
  OPTIONAL { ?point ref:hasExternalReference ?o ; ref:hasTimeseriesId ?ts } .
  FILTER (STRSTARTS(STR(?point), "http://w3id.org/")) .
}

